   pure subroutine pcm_grad_item_01(ij, c, nshell, nao, natm, maxnp, sh_np, sh_ao, sh_at, sh_e, sh_c, sh_r, npair, p_i, p_j, npts, pts, zk, ptatm, q, dmat, nch, nlane, gp)
      !! One (shell pair, share of the points)'s PCM gradient block, lane-
      !! accumulated exactly as trc_1e_grad_k01's own item -- the old
      !! trc_pcm_grad_driver.inc's pcm_grad_item, specialised to this class
      !! (no sh_l, no runtime dispatch).
      !$acc routine seq
      integer,  intent(in)  :: ij, c
      integer,  intent(in)  :: nshell, nao, natm, maxnp, npair, npts, nch, nlane
      integer,  intent(in)  :: sh_np(nshell), sh_ao(nshell), sh_at(nshell)
      real(dp), intent(in)  :: sh_e(maxnp, nshell), sh_c(maxnp, nshell)
      real(dp), intent(in)  :: sh_r(3, nshell)
      integer,  intent(in)  :: p_i(npair), p_j(npair)
      real(dp), intent(in)  :: pts(3, npts), zk(npts), q(npts)
      integer,  intent(in)  :: ptatm(npts)
      real(dp), intent(in)  :: dmat(nao, nao)
      real(dp), intent(inout) :: gp(3, natm, nlane)

      integer  :: ii, jj, a, b, mu, nu, lane, npt, k0
      real(dp) :: wt, ga(3), gb(3)
      real(dp) :: dblk(3)

      ii = p_i(ij); jj = p_j(ij)
      wt = merge(1.0_dp, 2.0_dp, ii == jj)
      lane = mod(ij - 1, nlane) + 1
      npt = (npts - c)/nch + 1
      k0 = c

      ! Affine index, not a running counter: nvfortran 26.5 fails "Missing
      ! increment value" on a counter used as a subscript in this loop
      ! nest once BOTH na and nb exceed 1 (trc_1e_grad_k01's own
      ! work-around, gen_1e.py's emit_grad_split).
      do b = 0, 2
         nu = sh_ao(jj) + b
         do a = 0, 0
            mu = sh_ao(ii) + a
            dblk(1 + a + 1*b) = dmat(mu, nu)
         end do
      end do

      call pcm_grad_01(sh_np(ii), sh_np(jj), sh_e(:, ii), sh_c(:, ii), &
                          sh_e(:, jj), sh_c(:, jj), sh_r(:, ii), sh_r(:, jj), &
                          npt, k0, nch, pts, zk, ptatm, q, natm, wt, dblk, ga, gb, &
                          gp(1:3, 1:natm, lane))

      ! ATOMIC, trc_1e_grad_k01's own reason: two (shell pair, chunk)
      ! items can share both a lane and an atom.
      !$acc atomic update
      gp(1, sh_at(ii), lane) = gp(1, sh_at(ii), lane) + ga(1)
      !$acc atomic update
      gp(2, sh_at(ii), lane) = gp(2, sh_at(ii), lane) + ga(2)
      !$acc atomic update
      gp(3, sh_at(ii), lane) = gp(3, sh_at(ii), lane) + ga(3)
      !$acc atomic update
      gp(1, sh_at(jj), lane) = gp(1, sh_at(jj), lane) + gb(1)
      !$acc atomic update
      gp(2, sh_at(jj), lane) = gp(2, sh_at(jj), lane) + gb(2)
      !$acc atomic update
      gp(3, sh_at(jj), lane) = gp(3, sh_at(jj), lane) + gb(3)
   end subroutine pcm_grad_item_01

   pure subroutine pcm_grad_01(nprim_a, nprim_b, ea, ca, eb, cb, ra, rb, &
                                  npt, k0, kstep, cpt, zk, ptatm, q, natm, &
                                  wt, dblk, ga, gb, gc)
      !! (0|1) PCM surface-integral gradient block: +D:dV/dR of
      !! sum_k q_k erf(zeta_k|r-C_k|)/|r-C_k| over the npt points
      !! k = k0, k0 + kstep, ... -- basis-centre derivative into ga/gb,
      !! point derivative atomically into gc(:, ptatm(k)). See
      !! emit_pcm_grad_class/emit_dc_vrr in scripts/gen_1e.py.
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_b, npt, k0, kstep, natm
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a)
      real(dp), intent(in)  :: eb(nprim_b), cb(nprim_b)
      real(dp), intent(in)  :: ra(3), rb(3)
      real(dp), intent(in)  :: cpt(3, *)     !! point centres
      real(dp), intent(in)  :: zk(*)         !! zeta_k; the Gaussian exponent is zeta_k^2
      integer,  intent(in)  :: ptatm(*)      !! the point's parent atom, 1-based
      real(dp), intent(in)  :: q(*)          !! the surface charge at each point
      real(dp), intent(in)  :: wt, dblk(3)
      real(dp), intent(out)   :: ga(3), gb(3)
      real(dp), intent(inout) :: gc(3, natm)

      integer  :: ip, jp, ic, k, kk, m, pa
      real(dp) :: al, bet, zeta, oo2z, xi, cc
      real(dp) :: px, py, pz, pax, pay, paz, pbx, pby, pbz
      real(dp) :: pcx, pcy, pcz, tval, vpref0, vpref, rab2
      real(dp) :: abx, aby, abz, w2, theta, thm
      real(dp) :: vn(10,0:2), vn0(10)
      real(dp) :: wx(4,0:1), wy(4,0:1), wz(4,0:1)
      real(dp) :: wx0(4), wy0(4), wz0(4)
      real(dp) :: vAp(9)
      real(dp) :: vBp(6)
      real(dp) :: vBm(1)
      real(dp) :: wxt(3), wyt(3), wzt(3)
      real(dp) :: f(0:BOYS_MMAX)

      abx = ra(1) - rb(1); aby = ra(2) - rb(2); abz = ra(3) - rb(3)
      rab2 = abx*abx + aby*aby + abz*abz

      ga = 0.0_dp; gb = 0.0_dp

      do ip = 1, nprim_a
         al = ea(ip)
      do jp = 1, nprim_b
         bet = eb(jp)
         zeta = al + bet
         oo2z = 0.5_dp/zeta
         xi = al*bet/zeta
         cc = ca(ip)*cb(jp)*wt

         px = (al*ra(1) + bet*rb(1))/zeta
         py = (al*ra(2) + bet*rb(2))/zeta
         pz = (al*ra(3) + bet*rb(3))/zeta
         pax = px - ra(1); pay = py - ra(2); paz = pz - ra(3)
         pbx = px - rb(1); pby = py - rb(2); pbz = pz - rb(3)

         vpref0 = 2.0_dp*PI/zeta*exp(-xi*rab2)

         do ic = 1, npt
            kk = k0 + (ic - 1)*kstep
            pcx = px - cpt(1, kk)
            pcy = py - cpt(2, kk)
            pcz = pz - cpt(3, kk)
            w2 = zk(kk)*zk(kk)
            theta = w2/(w2 + zeta)
            tval = theta*zeta*(pcx*pcx + pcy*pcy + pcz*pcz)
            call boys_eval(2, tval, f)
            thm = 1.0_dp
            do m = 1, 2
               thm = thm*theta
               f(m) = f(m)*thm
            end do
            vpref = vpref0*sqrt(theta)

            ! --- m = 2 ---
            vn(1,2) = vpref*f(2)
            ! --- m = 1 ---
            vn(1,1) = vpref*f(1)
            vn(2,1) = pax*vn(1,1) - pcx*vn(1,2)
            vn(3,1) = pay*vn(1,1) - pcy*vn(1,2)
            vn(4,1) = paz*vn(1,1) - pcz*vn(1,2)
            ! --- m = 0 ---
            vn(1,0) = vpref*f(0)
            vn(2,0) = pax*vn(1,0) - pcx*vn(1,1)
            vn(3,0) = pay*vn(1,0) - pcy*vn(1,1)
            vn(4,0) = paz*vn(1,0) - pcz*vn(1,1)
            vn(5,0) = pax*vn(2,0) - pcx*vn(2,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(6,0) = pax*vn(3,0) - pcx*vn(3,1)
            vn(7,0) = pax*vn(4,0) - pcx*vn(4,1)
            vn(8,0) = pay*vn(3,0) - pcy*vn(3,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(9,0) = pay*vn(4,0) - pcy*vn(4,1)
            vn(10,0) = paz*vn(4,0) - pcz*vn(4,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))

            ! --- dV/dC, m = 1 ---
            wx(1,1) = 2.0_dp*zeta*pcx*vn(1,2)
            wy(1,1) = 2.0_dp*zeta*pcy*vn(1,2)
            wz(1,1) = 2.0_dp*zeta*pcz*vn(1,2)
            ! --- dV/dC, m = 0 ---
            wx(1,0) = 2.0_dp*zeta*pcx*vn(1,1)
            wy(1,0) = 2.0_dp*zeta*pcy*vn(1,1)
            wz(1,0) = 2.0_dp*zeta*pcz*vn(1,1)
            wx(2,0) = pax*wx(1,0) - pcx*wx(1,1) &
               + vn(1,1)
            wy(2,0) = pax*wy(1,0) - pcx*wy(1,1)
            wz(2,0) = pax*wz(1,0) - pcx*wz(1,1)
            wx(3,0) = pay*wx(1,0) - pcy*wx(1,1)
            wy(3,0) = pay*wy(1,0) - pcy*wy(1,1) &
               + vn(1,1)
            wz(3,0) = pay*wz(1,0) - pcy*wz(1,1)
            wx(4,0) = paz*wx(1,0) - pcz*wx(1,1)
            wy(4,0) = paz*wy(1,0) - pcz*wy(1,1)
            wz(4,0) = paz*wz(1,0) - pcz*wz(1,1) &
               + vn(1,1)

            do k = 1, 10
               vn0(k) = vn(k,0)
            end do
            do k = 1, 4
               wx0(k) = wx(k,0); wy0(k) = wy(k,0); wz0(k) = wz(k,0)
            end do

            vAp(1) = abx*vn0(2) &
               + vn0(5)
            vAp(2) = abx*vn0(3) &
               + vn0(6)
            vAp(3) = abx*vn0(4) &
               + vn0(7)
            vAp(4) = aby*vn0(2) &
               + vn0(6)
            vAp(5) = aby*vn0(3) &
               + vn0(8)
            vAp(6) = aby*vn0(4) &
               + vn0(9)
            vAp(7) = abz*vn0(2) &
               + vn0(7)
            vAp(8) = abz*vn0(3) &
               + vn0(9)
            vAp(9) = abz*vn0(4) &
               + vn0(10)

            ! la = 0: no (la-1,lb) class

            vBp(1) = abx*abx*vn0(1) &
               + 2.0_dp*abx*vn0(2) &
               + vn0(5)
            vBp(2) = abx*aby*vn0(1) &
               + abx*vn0(3) &
               + aby*vn0(2) &
               + vn0(6)
            vBp(3) = abx*abz*vn0(1) &
               + abx*vn0(4) &
               + abz*vn0(2) &
               + vn0(7)
            vBp(4) = aby*aby*vn0(1) &
               + 2.0_dp*aby*vn0(3) &
               + vn0(8)
            vBp(5) = aby*abz*vn0(1) &
               + aby*vn0(4) &
               + abz*vn0(3) &
               + vn0(9)
            vBp(6) = abz*abz*vn0(1) &
               + 2.0_dp*abz*vn0(4) &
               + vn0(10)

            vBm(1) = vn0(1)

            wxt(1) = abx*wx0(1) &
               + wx0(2)
            wxt(2) = aby*wx0(1) &
               + wx0(3)
            wxt(3) = abz*wx0(1) &
               + wx0(4)

            wyt(1) = abx*wy0(1) &
               + wy0(2)
            wyt(2) = aby*wy0(1) &
               + wy0(3)
            wyt(3) = abz*wy0(1) &
               + wy0(4)

            wzt(1) = abx*wz0(1) &
               + wz0(2)
            wzt(2) = aby*wz0(1) &
               + wz0(3)
            wzt(3) = abz*wz0(1) &
               + wz0(4)

            pa = ptatm(kk)
            ga(1) = ga(1) - cc*q(kk)*dblk(1)*(2.0_dp*al*vAp(1))
            gb(1) = gb(1) - cc*q(kk)*dblk(1)*(2.0_dp*bet*vBp(1) - 1.0_dp*vBm(1))
            !$acc atomic update
            gc(1,pa) = gc(1,pa) - cc*q(kk)*dblk(1)*wxt(1)
            ga(2) = ga(2) - cc*q(kk)*dblk(1)*(2.0_dp*al*vAp(2))
            gb(2) = gb(2) - cc*q(kk)*dblk(1)*(2.0_dp*bet*vBp(2))
            !$acc atomic update
            gc(2,pa) = gc(2,pa) - cc*q(kk)*dblk(1)*wyt(1)
            ga(3) = ga(3) - cc*q(kk)*dblk(1)*(2.0_dp*al*vAp(3))
            gb(3) = gb(3) - cc*q(kk)*dblk(1)*(2.0_dp*bet*vBp(3))
            !$acc atomic update
            gc(3,pa) = gc(3,pa) - cc*q(kk)*dblk(1)*wzt(1)
            ga(1) = ga(1) - cc*q(kk)*dblk(2)*(2.0_dp*al*vAp(4))
            gb(1) = gb(1) - cc*q(kk)*dblk(2)*(2.0_dp*bet*vBp(2))
            !$acc atomic update
            gc(1,pa) = gc(1,pa) - cc*q(kk)*dblk(2)*wxt(2)
            ga(2) = ga(2) - cc*q(kk)*dblk(2)*(2.0_dp*al*vAp(5))
            gb(2) = gb(2) - cc*q(kk)*dblk(2)*(2.0_dp*bet*vBp(4) - 1.0_dp*vBm(1))
            !$acc atomic update
            gc(2,pa) = gc(2,pa) - cc*q(kk)*dblk(2)*wyt(2)
            ga(3) = ga(3) - cc*q(kk)*dblk(2)*(2.0_dp*al*vAp(6))
            gb(3) = gb(3) - cc*q(kk)*dblk(2)*(2.0_dp*bet*vBp(5))
            !$acc atomic update
            gc(3,pa) = gc(3,pa) - cc*q(kk)*dblk(2)*wzt(2)
            ga(1) = ga(1) - cc*q(kk)*dblk(3)*(2.0_dp*al*vAp(7))
            gb(1) = gb(1) - cc*q(kk)*dblk(3)*(2.0_dp*bet*vBp(3))
            !$acc atomic update
            gc(1,pa) = gc(1,pa) - cc*q(kk)*dblk(3)*wxt(3)
            ga(2) = ga(2) - cc*q(kk)*dblk(3)*(2.0_dp*al*vAp(8))
            gb(2) = gb(2) - cc*q(kk)*dblk(3)*(2.0_dp*bet*vBp(5))
            !$acc atomic update
            gc(2,pa) = gc(2,pa) - cc*q(kk)*dblk(3)*wyt(3)
            ga(3) = ga(3) - cc*q(kk)*dblk(3)*(2.0_dp*al*vAp(9))
            gb(3) = gb(3) - cc*q(kk)*dblk(3)*(2.0_dp*bet*vBp(6) - 1.0_dp*vBm(1))
            !$acc atomic update
            gc(3,pa) = gc(3,pa) - cc*q(kk)*dblk(3)*wzt(3)
         end do
      end do
      end do
   end subroutine pcm_grad_01

